contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(putAmount > 0 && putAmount <= address(this).balance);
        require(collectAmount > 0 && collectAmount <= putAmount);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockTime, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(balanceBefore == putAmount);
        require(block.timestamp > unlockTime || lockTime == 0);

        uint senderBalanceBefore = address(this).balance;
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint senderBalanceAfter = address(this).balance;
        uint cBalanceAfter = address(c).balance;

        assert(
            reverted
            || (
                balanceAfter == balanceBefore - collectAmount
                && senderBalanceAfter == senderBalanceBefore + collectAmount
                && cBalanceAfter == cBalanceBefore - collectAmount
            )
        );
    }

    receive() external payable {}
}

