    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(putAmount > 0 && putAmount <= address(this).balance);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        try c.SetMinSum(0) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 unlockTime;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTime = __r0; balanceBefore = __r1; } catch { return; }
        putAmount = balanceBefore;
        vm.assume(block.timestamp > unlockTime || lockTime == 0);
        uint senderBalanceBefore = address(this).balance;
        uint cBalanceBefore = address(c).balance;
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        uint256 unlockTimeAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeAfter = __r0; balanceAfter = __r1; } catch { return; }
        uint senderBalanceAfter = address(this).balance;
        uint cBalanceAfter = address(c).balance;
        assertTrue(reverted
            || (
                balanceAfter == balanceBefore - collectAmount
                && senderBalanceAfter == senderBalanceBefore + collectAmount
                && cBalanceAfter == cBalanceBefore - collectAmount
            ));
    }

    function testFuzz_run(uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        _run(lockTime, putAmount, collectAmount);
    }

    receive() external payable {}
}
